Approach ACK

Can we use this PR to also add the bash completation? See `bitcoin-cli.bash`.
```diff
diff --git a/contrib/completions/bash/bitcoin-cli.bash b/contrib/completions/bash/bitcoin-cli.bash
index ff34ad9ff6..2559c5530a 100644
--- a/contrib/completions/bash/bitcoin-cli.bash
+++ b/contrib/completions/bash/bitcoin-cli.bash
@@ -9,7 +9,7 @@ _bitcoin_rpc() {
     local rpcargs=()
     for i in ${COMP_LINE}; do
         case "$i" in
-            -conf=*|-datadir=*|-regtest|-rpc*|-testnet|-testnet4)
+            -conf=*|-datadir=*|-regtest|-rpc*|-testnet|-testnet4|-testnet5)
                 rpcargs=( "${rpcargs[@]}" "$i" )
                 ;;
         esac

```
Should we add tests for the restored difficulty behavior?

Maybe also some activation unit tests? Maybe test that block1 has bip54 active?
```diff
diff --git a/src/test/versionbits_tests.cpp b/src/test/versionbits_tests.cpp
index 7dcc5c676c..361be3f3d6 100644
--- a/src/test/versionbits_tests.cpp
+++ b/src/test/versionbits_tests.cpp
@@ -5,6 +5,7 @@
 #include <chain.h>
 #include <chainparams.h>
 #include <consensus/params.h>
+#include <deploymentstatus.h>
 #include <test/util/random.h>
 #include <test/util/common.h>
 #include <test/util/setup_common.h>
@@ -492,4 +493,20 @@ BOOST_FIXTURE_TEST_CASE(versionbits_computeblockversion, BlockVersionTest)
     }
 }
 
+BOOST_AUTO_TEST_CASE(testnet5_consensuscleanup_activation)
+{
+    for (const auto chain_type : {ChainType::TESTNET4, ChainType::TESTNET5}) {
+        BOOST_TEST_CONTEXT(ChainTypeToString(chain_type)) {
+            const auto chain_params{CreateChainParams(ArgsManager{}, chain_type)};
+            // Evaluate block 1 with the default deployment parameters, without mining genesis.
+            CBlockIndex genesis{chain_params->GenesisBlock()};
+            genesis.nHeight = 0;
+            VersionBitsCache cache;
+            BOOST_CHECK_EQUAL(DeploymentActiveAfter(&genesis, chain_params->GetConsensus(),
+                                                   Consensus::DEPLOYMENT_CONSENSUSCLEANUP, cache),
+                              chain_type == ChainType::TESTNET5);
+        }
+    }
+}

```

